pub struct Segment {
    pub first: usize,
    pub second: usize,
    pub squared_length: u64,
    pub low_angle: i32,
    pub high_angle: i32,
    pub orientation: i32,
    pub reversed: bool,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Correspondence {
    pub probe_index: usize,
    pub gallery_index: usize,
    pub orientation_delta: i32,
    pub score: u64,
}

fn normalize(angle: i64) -> i32 {
    ((angle + 180).rem_euclid(360) - 180) as i32
}

fn circular_distance(a: i32, b: i32) -> u64 {
    u64::from(normalize(i64::from(a) - i64::from(b)).unsigned_abs())
}

pub fn match_segments(
    probe: &[Segment],
    gallery: &[Segment],
    length_tolerance: u64,
    angle_tolerance: i32,
    strict: bool,
) -> Vec<Correspondence> {
    if angle_tolerance < 0 {
        return Vec::new();
    }
    let count = if strict { probe.len().saturating_sub(1) } else { probe.len() };
    let mut result = Vec::new();
    for (probe_index, p) in probe[..count].iter().enumerate() {
        for (gallery_index, g) in gallery.iter().enumerate() {
            let length_delta = p.squared_length.abs_diff(g.squared_length);
            let low_delta = circular_distance(p.low_angle, g.low_angle);
            let high_delta = circular_distance(p.high_angle, g.high_angle);
            if length_delta <= length_tolerance
                && low_delta <= angle_tolerance as u64
                && high_delta <= angle_tolerance as u64
            {
                let gallery_orientation = if p.reversed == g.reversed {
                    i64::from(g.orientation)
                } else {
                    -i64::from(g.orientation)
                };
                result.push(Correspondence {
                    probe_index,
                    gallery_index,
                    orientation_delta: normalize(gallery_orientation + i64::from(p.orientation)),
                    score: length_delta + low_delta + high_delta,
                });
            }
        }
    }
    result
}

