#[path = "solution.rs"]
mod solution;

use solution::{match_segments, Correspondence, Segment};

fn segment(length: u64, low: i32, high: i32, orientation: i32, reversed: bool) -> Segment {
    Segment {
        first: 11,
        second: 22,
        squared_length: length,
        low_angle: low,
        high_angle: high,
        orientation,
        reversed,
    }
}

#[test]
fn empty_inputs_and_negative_angle_tolerance_produce_no_matches() {
    let s = segment(10, 0, 0, 0, false);
    assert!(match_segments(&[], &[s], 0, 0, false).is_empty());
    assert!(match_segments(&[s], &[], 0, 0, false).is_empty());
    assert!(match_segments(&[s], &[s], u64::MAX, -1, false).is_empty());
}

#[test]
fn matching_uses_inclusive_length_and_angle_tolerances() {
    let probe = [segment(100, 350, 10, 0, false)];
    let gallery = [
        segment(105, 5, 355, 0, false),
        segment(106, 5, 355, 0, false),
        segment(105, 6, 355, 0, false),
        segment(105, 5, 354, 0, false),
    ];
    let result = match_segments(&probe, &gallery, 5, 15, false);
    assert_eq!(
        result,
        vec![Correspondence {
            probe_index: 0,
            gallery_index: 0,
            orientation_delta: 0,
            score: 35,
        }]
    );
}

#[test]
fn angles_are_compared_modulo_360_with_negative_values() {
    let probe = [segment(7, -10, 721, 0, false)];
    let gallery = [segment(7, 350, 1, 0, false)];
    assert_eq!(
        match_segments(&probe, &gallery, 0, 0, false),
        vec![Correspondence {
            probe_index: 0,
            gallery_index: 0,
            orientation_delta: 0,
            score: 0,
        }]
    );
}

#[test]
fn orientation_delta_honors_reversal_and_normalization() {
    let probe = [segment(1, 0, 0, 30, false)];
    let gallery = [
        segment(1, 0, 0, 100, false),
        segment(1, 0, 0, 100, true),
        segment(1, 0, 0, 210, false),
        segment(1, 0, 0, -151, false),
    ];
    let result = match_segments(&probe, &gallery, 0, 0, false);
    assert_eq!(result[0].orientation_delta, 70);
    assert_eq!(result[1].orientation_delta, -130);
    assert_eq!(result[2].orientation_delta, -180);
    assert_eq!(result[3].orientation_delta, 179);
}

#[test]
fn score_is_the_sum_of_all_three_distances() {
    let probe = [segment(50, 10, 340, 5, false)];
    let gallery = [segment(43, 350, 5, 7, false)];
    assert_eq!(
        match_segments(&probe, &gallery, 7, 25, false),
        vec![Correspondence {
            probe_index: 0,
            gallery_index: 0,
            orientation_delta: 2,
            score: 52,
        }]
    );
}

#[test]
fn all_matches_are_retained_in_probe_major_gallery_major_order() {
    let probe = [
        segment(10, 0, 0, 0, false),
        segment(20, 0, 0, 0, false),
    ];
    let gallery = [
        segment(10, 0, 0, 0, false),
        segment(20, 0, 0, 0, false),
    ];
    let indices: Vec<(usize, usize)> = match_segments(&probe, &gallery, 10, 0, false)
        .into_iter()
        .map(|c| (c.probe_index, c.gallery_index))
        .collect();
    assert_eq!(indices, vec![(0, 0), (0, 1), (1, 0), (1, 1)]);
}

#[test]
fn strict_mode_omits_only_the_last_probe_segment() {
    let probe = [
        segment(1, 0, 0, 0, false),
        segment(1, 0, 0, 0, false),
        segment(1, 0, 0, 0, false),
    ];
    let gallery = [segment(1, 0, 0, 0, false)];
    let result = match_segments(&probe, &gallery, 0, 0, true);
    assert_eq!(result.len(), 2);
    assert_eq!(result[0].probe_index, 0);
    assert_eq!(result[1].probe_index, 1);

    assert!(match_segments(&probe[..1], &gallery, 0, 0, true).is_empty());
    assert!(match_segments(&[], &gallery, 0, 0, true).is_empty());
}

#[test]
fn inputs_are_not_mutated_and_results_are_deterministic() {
    let probe = [segment(12, 20, 30, 40, false)];
    let gallery = [segment(13, 21, 29, 42, true)];
    let probe_before = probe;
    let gallery_before = gallery;
    let first = match_segments(&probe, &gallery, 2, 2, false);
    let second = match_segments(&probe, &gallery, 2, 2, false);
    assert_eq!(first, second);
    assert_eq!(probe, probe_before);
    assert_eq!(gallery, gallery_before);
}

